  let aS=0, iS1=0, iS2=0, cross=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a = Math.sin(d*f-t*sp)*w;
    const i1 = Math.sin(d*f*0.6+t*sp*0.5+1.5)*w;
    const i2 = Math.sin(d*f*0.4-t*sp*0.3+3.0)*w*0.7;
    aS += a; iS1 += i1; iS2 += i2;
    cross += a*i1*0.15;
  }
  const n = 8;
  aS/=n; iS1/=n; iS2/=n; cross/=n;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.025-sy*0.035+t*0.95))/2;
