  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin((sx-sy*0.7)*0.08-t*0.7)*0.3)*1.4)*0.28;
  const fiber=Math.sin(sx*0.05+t*0.5)*Math.cos(sy*0.04-t*0.4)*0.15*Math.sin(ang*2+t*0.3);
  const pulse=1.0+Math.sin(t*0.8)*0.08+Math.sin(t*1.3)*0.04;
  const blend=(react*0.65+cell*0.2+fiber*0.15)*pulse, v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,95],[18,95,125],[30,155,145],[140,195,120],[220,195,65],[215,140,60],[195,85,75],[140,45,80],[70,22,65],[5,12,52]];
